"use client";

import { useEffect, useState } from "react";
import DataTable from "@/components/admin/DataTable";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Trash2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

export default function AdminTeamsPage() {
    const [teams, setTeams] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const { toast } = useToast();

    const fetchTeams = async () => {
        try {
            const res = await fetch("/api/admin/teams");
            if (res.ok) {
                const data = await res.json();
                setTeams(data.teams || []);
            }
        } catch (error) {
            console.error("Failed to fetch teams:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchTeams();

        const channel = supabase.channel("admin-teams")
          .on("postgres_changes", { event: "*", schema: "public", table: "teams" }, () => fetchTeams())
          .subscribe();

        return () => { supabase.removeChannel(channel); };
    }, []);

    const handleDeleteTeam = async (teamId: string) => {
        const confirmed = window.confirm("Are you sure you want to delete this team? Cascading deletions may remove applications.");
        if (!confirmed) return;

        try {
            const res = await fetch("/api/admin/teams", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ targetTeamId: teamId, action: "delete" })
            });

            if (res.ok) {
                toast({ title: "Team Deleted" });
                setTeams(prev => prev.filter(t => t.id !== teamId));
            } else {
                const err = await res.json();
                toast({ title: "Error", description: err.error, variant: "destructive" });
            }
        } catch (error: any) {
             toast({ title: "Error", description: error.message, variant: "destructive" });
        }
    };

    const columns = [
        { 
            header: "Team Name", 
            accessor: (row: any) => (
                <div className="font-semibold text-slate-900 dark:text-white">
                  {row.name}
                </div>
            ) 
        },
        { 
            header: "Leader", 
            accessor: (row: any) => {
               const leader = row.team_members?.find((m:any) => m.role === "Leader" || m.role === "admin");
               return (
                   <div>
                       {leader ? <div className="font-medium">{leader.name}</div> : <span className="text-slate-400 italic">No Leader Found</span>}
                       {leader && <div className="text-xs text-slate-500">{leader.email}</div>}
                   </div>
               )
            }
        },
        { 
            header: "Members", 
            accessor: (row: any) => (
               <Badge variant="secondary">
                   {row.team_members?.length || 0} Members
               </Badge>
            )
        },
        {
            header: "Actions",
            accessor: (row: any) => (
                <div className="flex items-center gap-2">
                    <Button variant="outline" size="sm" className="text-destructive hover:bg-destructive hover:text-white h-8 w-8 p-0" onClick={() => handleDeleteTeam(row.id)}>
                        <Trash2 className="h-4 w-4" />
                    </Button>
                </div>
            )
        }
    ];

    if (loading) return <div className="animate-pulse h-64 bg-slate-200 dark:bg-slate-800 rounded-xl"></div>;

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                   <h1 className="text-2xl font-bold font-display text-slate-900 dark:text-white">Team Management</h1>
                   <p className="text-slate-500 mt-1">Manage project teams and detect abnormal group activity.</p>
                </div>
            </div>

            <DataTable columns={columns} data={teams} keyExtractor={(row) => row.id} />
        </div>
    );
}
